import json
import math
import sys

HARD_GATES = [
    "quality_evaluation_passed",
    "identity_enforced",
    "tenant_isolation_tested",
    "prompt_retention_approved",
    "streaming_contract_passed",
    "tool_contract_passed",
    "retry_idempotency_passed",
    "bypass_blocked",
]

ROUTE_NUMERIC_FIELDS = [
    "quality",
    "p95_latency_ms",
    "reliability",
    "input_rate_per_1k",
    "output_rate_per_1k",
    "request_fee",
]


def number(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{name}: expected finite number")
    try:
        converted = float(value)
    except OverflowError:
        raise ValueError(f"{name}: expected finite number") from None
    if not math.isfinite(converted):
        raise ValueError(f"{name}: expected finite number")
    return converted


def count(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{name}: expected finite number")
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError(f"{name}: expected finite number")
        raise ValueError(f"{name}: expected nonnegative integer")
    if value < 0:
        raise ValueError(f"{name}: expected nonnegative integer")
    return value


def nonnegative_number(value, name):
    converted = number(value, name)
    if converted < 0.0:
        raise ValueError(f"{name}: expected nonnegative finite number")
    return converted


def unit_interval(value, name):
    converted = number(value, name)
    if converted < 0.0 or converted > 1.0:
        raise ValueError(f"{name}: expected number in range 0..1")
    return converted


def require_fields(value, fields, context):
    for field in fields:
        if field not in value:
            raise ValueError(f"{context}: missing required field {field}")


def validate_request(request):
    if not isinstance(request, dict):
        raise ValueError("request: expected object")
    require_fields(request, ["input_tokens", "output_tokens"], "request")
    return {
        "input_tokens": count(request["input_tokens"], "input_tokens"),
        "output_tokens": count(request["output_tokens"], "output_tokens"),
    }


def validate_route(route, name):
    if not isinstance(route, dict):
        raise ValueError(f"route {name}: expected object")
    require_fields(route, ROUTE_NUMERIC_FIELDS, f"route {name}")
    return {
        "quality": unit_interval(route["quality"], "quality"),
        "p95_latency_ms": nonnegative_number(
            route["p95_latency_ms"], "p95_latency_ms"
        ),
        "reliability": unit_interval(route["reliability"], "reliability"),
        "input_rate_per_1k": nonnegative_number(
            route["input_rate_per_1k"], "input_rate_per_1k"
        ),
        "output_rate_per_1k": nonnegative_number(
            route["output_rate_per_1k"], "output_rate_per_1k"
        ),
        "request_fee": nonnegative_number(route["request_fee"], "request_fee"),
    }


def validate_fixture(fixture):
    if not isinstance(fixture, dict):
        raise ValueError("fixture: expected object")
    if "request" not in fixture:
        raise ValueError("fixture: missing required field request")
    if "routes" not in fixture:
        raise ValueError("fixture: missing required field routes")

    request = validate_request(fixture["request"])
    routes = fixture["routes"]
    if not isinstance(routes, dict):
        raise ValueError("routes: expected object")
    if not routes:
        raise ValueError("routes: expected at least one route")

    validated_routes = {}
    for name, route in routes.items():
        if not isinstance(name, str) or not name:
            raise ValueError("routes: expected nonempty string route names")
        validated_routes[name] = validate_route(route, name)
    return request, validated_routes


def cost(route, request):
    return (
        request["input_tokens"] / 1000.0 * route["input_rate_per_1k"]
        + request["output_tokens"] / 1000.0 * route["output_rate_per_1k"]
        + route["request_fee"]
    )


def evaluate(route, validated_route, request):
    missing = [key for key in HARD_GATES if key not in route]
    failed = [
        key for key in HARD_GATES
        if key in route and route[key] is not True
    ]
    if missing or failed:
        reasons = []
        if missing:
            reasons.append("missing=" + ",".join(missing))
        if failed:
            reasons.append("failed=" + ",".join(failed))
        return {"eligible": False, "reason": ";".join(reasons)}

    normalized_cost = cost(validated_route, request)
    quality = validated_route["quality"]
    latency = validated_route["p95_latency_ms"]
    reliability = validated_route["reliability"]
    score = (
        0.50 * quality
        + 0.20 * (1.0 - latency / 1000.0)
        + 0.20 * (1.0 - normalized_cost / 0.0100)
        + 0.10 * reliability
    )
    return {
        "eligible": True,
        "cost": normalized_cost,
        "score": score,
        "latency": latency,
    }


def main():
    if len(sys.argv) != 2:
        raise ValueError("usage: python3 evaluator.py FIXTURE.json")

    with open(sys.argv[1], encoding="utf-8") as handle:
        fixture = json.load(handle)

    request, validated_routes = validate_fixture(fixture)
    results = {}
    for name, route in fixture["routes"].items():
        results[name] = evaluate(route, validated_routes[name], request)

    eligible = {
        name: result
        for name, result in results.items()
        if result["eligible"]
    }
    if not eligible:
        raise ValueError("no eligible route")

    winner = max(eligible, key=lambda name: eligible[name]["score"])
    print(f"decision={winner}")
    for name in fixture["routes"]:
        result = results[name]
        if not result["eligible"]:
            print(f"{name}: DENY ({result['reason']})")
        else:
            print(
                f"{name}: ALLOW score={result['score']:.4f} "
                f"cost=${result['cost']:.4f} "
                f"latency_p95_ms={result['latency']:.1f}"
            )


if __name__ == "__main__":
    try:
        main()
    except (KeyError, TypeError, ValueError, json.JSONDecodeError) as error:
        print(f"ERROR: {error}")
        sys.exit(1)

